"""Randomised differential test: reference implementation vs the Rust engine."""
import json, random, sys, subprocess, time
sys.path.insert(0, '/workspace/tmp')
import reference

def random_topology(rng):
    choice = rng.randrange(6)
    if choice == 0:
        k = rng.choice([4, 6, 8])
        return ['clos', k, rng.choice(['tor', 'pod']), rng.choice([0, 1])]
    if choice == 1:
        return ['leaf-spine', rng.randint(2, 5), rng.randint(1, 3)]
    if choice == 2:
        return ['torus2d', rng.randint(3, 5), rng.choice(['host', 'row'])]
    if choice == 3:
        return ['torus3d', 3, rng.choice(['host', 'line'])]
    if choice == 4:
        g = rng.randint(2, 5); a = rng.randint(1, 3)
        h = (g - 1) // a
        if a * h != g - 1: return ['dragonfly', 2, 1, 1, 'router']
        return ['dragonfly', g, a, h, rng.choice(['router', 'group', 'target'])]
    g = rng.randint(2, 4); l = rng.randint(1, 3); s = rng.randint(1, 3)
    dense = rng.choice([0, 1])
    if not dense and (g - 1) % s: dense = 1
    h = max(1, (g - 1) // s)
    return ['dragonfly-plus', g, l, s, h, dense, rng.choice(['tor', 'group'])]

def random_session(rng, legal=True):
    topo = reference.Topology(random_topology(rng))
    ngroups = rng.randint(1, 4)
    ntasks = rng.randint(0, 8)
    groups = []
    for g in range(ngroups):
        quota = rng.randint(1, 4)
        budget = rng.randint(1, 20)
        groups.append([quota, budget])
    domains = sorted(set(topo.domains))
    group_domain = [rng.choice(domains) for _ in range(ngroups)]
    group_class = [rng.randint(0, 3) for _ in range(ngroups)]
    tasks = []
    for t in range(ntasks):
        g = rng.randrange(ngroups)
        cand = [i for i, d in enumerate(topo.domains) if d == group_domain[g]]
        tmpl = rng.choice(cand)
        weight = rng.randint(1, 10)
        tasks.append([tmpl, g, weight, group_class[g], rng.choice([0, 0, 1])])
    state = reference.State(topo, [0] * topo.n, groups, tasks)
    use = state.usage()
    caps = [u + rng.choice([0, 0, 1, 5]) for u in use]
    state.caps = caps
    # make budgets workable
    load = state.loads()
    for g in range(ngroups):
        if load[g]:
            need = (load[g] + groups[g][1] - 1) // groups[g][1]
            if need > groups[g][0]:
                groups[g][0] = min(64, need)
    if not legal:
        mode = rng.randrange(4)
        if mode == 0 and ngroups:
            groups[rng.randrange(ngroups)][0] = 0
        elif mode == 1 and ntasks >= 2:
            tasks[-1][3] = (tasks[-1][3] + 1) % 7
        elif mode == 2:
            caps[rng.randrange(topo.n)] = 0
        elif mode == 3 and ngroups > 1:
            groups[rng.randrange(ngroups)][1] = 1
            # shrink budget so load may exceed
            for g in range(ngroups):
                if load[g] > groups[g][0] * groups[g][1]:
                    groups[g][1] = max(1, load[g] // max(1, groups[g][0]))
    session = {
        'topology': topo.spec,
        'caps': caps,
        'groups': groups,
        'tasks': tasks,
        'query': {'groups': list(range(ngroups)), 'nodes': list(range(topo.n)), 'tasks': list(range(ntasks))},
        'transactions': [],
    }
    revision = 0
    for _ in range(rng.randint(0, 6)):
        use_revision = revision if rng.random() < 0.8 else rng.randint(0, 5)
        edits = []
        for _ in range(rng.randint(0, 4)):
            op = rng.choice(['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap'])
            if op in ('move', 'weight', 'class', 'bind', 'pin'):
                if not ntasks: continue
                t = rng.randrange(ntasks)
                if op == 'move': edits.append(['move', t, rng.randrange(ngroups)])
                elif op == 'weight': edits.append(['weight', t, rng.randint(1, 20)])
                elif op == 'class': edits.append(['class', t, rng.randint(0, 5)])
                elif op == 'bind': edits.append(['bind', t, rng.randrange(len(topo.pairs))])
                else: edits.append(['pin', t, rng.choice([0, 1])])
            elif op in ('quota', 'budget'):
                g = rng.randrange(ngroups)
                if op == 'quota': edits.append(['quota', g, rng.randint(0, 6)])
                else: edits.append(['budget', g, rng.randint(1, 30)])
            else:
                edits.append(['cap', rng.randrange(topo.n), rng.randint(0, 40)])
        q = {'groups': [rng.randrange(ngroups) for _ in range(rng.randint(0, 3))],
             'nodes': [rng.randrange(topo.n) for _ in range(rng.randint(0, 3))],
             'tasks': [rng.randrange(ntasks) for _ in range(rng.randint(0, 3))] if ntasks else []}
        session['transactions'].append({'revision': use_revision, 'edits': edits, 'query': q})
        revision += 1
    return session

def main():
    seed0 = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 50
    bad = 0
    for r in range(rounds):
        rng = random.Random(seed0 + r)
        nsessions = rng.randint(1, 3)
        sessions = [random_session(rng, legal=(rng.random() < 0.85)) for _ in range(nsessions)]
        request = {'version': 2, 'sessions': sessions}
        data = json.dumps(request, separators=(',', ':'))
        try:
            expected = reference.run(request)
        except ValueError:
            expected = {'error': 'invalid'}
        proc = subprocess.run([sys.executable, '-B', '/workspace/submission/main.py'],
                              input=data.encode(), stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=180)
        if proc.returncode != 0:
            print('seed', seed0 + r, 'NONZERO EXIT', proc.returncode, proc.stderr.decode()[:2000]); bad += 1; continue
        try:
            actual = json.loads(proc.stdout.decode())
        except Exception as exc:
            print('seed', seed0 + r, 'BAD JSON', exc, proc.stdout[:400], proc.stderr.decode()[:1000]); bad += 1; continue
        if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
            bad += 1
            print('seed', seed0 + r, 'MISMATCH')
            if bad <= 3:
                open('/workspace/tmp/fail-%d.json' % (seed0 + r), 'w').write(data)
                print('  saved request')
                # find the differing session
                for i, (a, e) in enumerate(zip(actual.get('sessions', []), expected.get('sessions', []))):
                    if json.dumps(a, sort_keys=True) != json.dumps(e, sort_keys=True):
                        print('  session', i, 'differs')
                        print('   actual  ', json.dumps(a)[:1500])
                        print('   expected', json.dumps(e)[:1500])
                        break
                if 'error' in expected or 'error' in actual:
                    print('  expected', json.dumps(expected)[:300]); print('  actual', json.dumps(actual)[:300])
    print('rounds', rounds, 'mismatches', bad)
    return 1 if bad else 0

if __name__ == '__main__':
    raise SystemExit(main())
